@yuwata 
This is also my question. 

Actually, before verified this solution, I have verified that delete path_id and path_wd both, or delete anything can solve the problem. And I think this is the real problem. As follow:
```
static void device_remove_watch_handle(sd_device *device) {
        const char *id;
        int wd;

        assert(device);

        /* First, remove the symlink from handle to device id. */
        wd = device_get_watch_handle(device);
        if (wd >= 0) {
                char path_wd[STRLEN("/run/udev/watch/") + DECIMAL_STR_MAX(int)];

                xsprintf(path_wd, "/run/udev/watch/%d", wd);
                if (access(path_wd, F_OK) < 0)
                        return;
                
                (void) unlink(path_wd);
        } else 
                return;

        /* Next, remove the symlink from device id to handle. */
        if (device_get_id_filename(device, &id) >= 0) {
                const char *path_id;

                path_id = strjoina("/run/udev/watch/", id);
                (void) unlink(path_id);
        }

        device->watch_handle = -1;
}
```
